#dim reqObj As IHC.ITF.ITFCOMMON.HDD.Interface.Object set listInd = pRequest.listOfHDDBillTypeobj.Next("") set list = ##class(%ListOfObjects).%New()
while ( listInd '= "") { set billTypeList = "" set reqObj = pRequest.listOfHDDBillTypeobj.GetAt(listInd) Do ..GetHelp1BillingType(reqObj.BillingType, .billTypeList)
set hddObj = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Object).%New() set hddObj.Comment = "Gets Help1 BillingType" set hddObj.BillingType = billTypeList set hddObj.Context = "" set hddObj.NCID = "" set hddObj.Domain = "" set hddObj.Rep = "" set hddObj.Index = reqObj.Index Do list.Insert(hddObj) set listInd = pRequest.listOfHDDBillTypeobj.Next(listInd) }
set pResponse = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.LookupResponse).%New() set pResponse.listOfHDDobj = list
Quit $$$OK

  try 
  {
 	Set billTypeList = ""
 	set billTypeList = ..GetHelp1BillingTypeFromHddBillingTypeCache(billTypeNcid)
 	if ( billTypeList '= ""){
	 	return
	} 		
	set servicePort = ##class(HddInterfaceService.InterfaceServicePort).%New()
	set servicePort.Location = ..Location

	Set listBillType = servicePort.getHelp1BillingType(billTypeNcid, ..dbEnv, 0)

	if (listBillType.Count() < 1){
	 	   $$$LOGERROR("HDD service did not return billing type for the Ncids : " _ billTypeNcids )
	 	   Set billTypeList = "ERROR"
 	}else{	     
 	        Set billTypeString = listBillType.GetAt(1)_":"_listBillType.GetAt(2)_":"_listBillType.GetAt(3)_":"_listBillType.GetAt(4)
		  	Do ..InsertValuesToHddBillingTypeCache(billTypeString, billTypeNcid)
		  	Set billTypeList = billTypeString
		 } 	
 }  
 CATCH exceptionvar
 {
     Set rep = "ERROR"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
	     Set repNcid = errTxt
         $$$LOGERROR("Exception in GetHelp1BillingType NCIDs(PV1.18,PV1.10): " _billTypeNcid _" = " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }
  }

#dim reqObj As IHC.ITF.ITFCOMMON.HDD.Interface.Object set listInd = pRequest.listOfHddRepObj.Next("") set list = ##class(%ListOfObjects).%New() set ncid = ""
while ( listInd '= "") { set rep = "" set reqObj = pRequest.listOfHddRepObj.GetAt(listInd) Do ..GetUniqueRepByNcid(reqObj.NCID, reqObj.Context, .rep)
set hddObj = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Object).%New() set hddObj.Comment = "Get Unique Representation for Ncid" set hddObj.NCID = reqObj.NCID set hddObj.Context = reqObj.Context set hddObj.Domain = "" set hddObj.Rep = rep set hddObj.Index = reqObj.Index Do list.Insert(hddObj) set listInd = pRequest.listOfHddRepObj.Next(listInd) }
set pResponse = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.LookupResponse).%New() set pResponse.listOfHDDobj = list
Quit $$$OK

  try 
  {
 	Set rep = ""
 	set rep = ..GetHddRepForNcidFromHddRepCache(ncid, context)
 	if (rep '= "")
	{
	  	return
	}	
	set servicePort = ##class(HddInterfaceService.InterfaceServicePort).%New()
	set servicePort.Location = ..Location

	Set code = servicePort.getUniqueRepByNcid(ncid, context, ..dbEnv, 0)
		  if $GET(code)
		  {
		  	Set rep = code.text
		  	$$$TRACE("getUniqueRepByNcid " _ ncid _ ": " _rep)
		  	Do ..InsertValuesToHddRepCache(ncid, context, rep)
		  	Quit
		  }
		  else
		  {
			  Set rep = "ERROR" 
		  }


 }  
 CATCH exceptionvar
 {
     Set rep = "ERROR"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
	     Set repNcid = errTxt
         $$$LOGERROR("Exception in GetUniqueRepByNcid NCID: " _ncid _", Context: " _ context _ " = " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }
  }

  try 
  {
	set repNcid = ""
	set repNcid = ..GetHddNcidForRepFromHddNcidCache(rep,domain,context)
    if ( repNcid '= "")
    {
	    return
    }
	set servicePort = ##class(HddInterfaceService.InterfaceServicePort).%New()

    set servicePort.Location = ..Location	 

 	Set repNcid = servicePort.getUniqueNcidByRep(rep, domain, context, ..dbEnv, 0) 
 	if ( repNcid '= ""){
		$$$TRACE("getUniqueNcidByRep " _ repNcid) 	
		Do ..InsertValuesToHddNcidCache(repNcid, domain, context, rep)
		Quit
	}else{
		Set repNcid = "ERROR"
	}	 
  } 	
    CATCH exceptionvar
    {
	  Set repNcid = "ERROR in GetUniqueNcidByRep method"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
         $$$LOGERROR("Exception in GetUniqueNcidByRep  Rep: " _ rep _ ", domain: " _ Domain _ ", Context:" _ context _ " = " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location )
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }

    }

	 //Get current time
 SET todayInt=$PIECE($HOROLOG,",",1)
 SET nowInt=$PIECE($HOROLOG,",",2)
 $$$TRACE( "Now: (" _ todayInt _ ", " _ nowInt _")")

 if ($DATA(^NextRef) = 0)
 {
	 $$$TRACE(  "Set global: ^NextRef")
	 set ^NextRef(1)= todayInt _ "," _ (nowInt - 50)
 }

 // Get Next refresh time
 SET nextdateref=$PIECE($GET(^NextRef(1)),",",1)
 SET nexttimeref=$PIECE($GET(^NextRef(1)),",",2)

 $$$TRACE(  "NEXT REFRESH: (" _ nextdateref _ ", " _ nexttimeref _")")


 if ((todayInt < nextdateref) || ((todayInt = nextdateref) && (nowInt < nexttimeref)) )
 {
	 $$$TRACE( "REFRESH Due on: " _ $ZDATETIME(^NextRef(1)) _ " = " _(nextdateref - todayInt) _ " : " _ (nexttimeref - nowInt))
 }
 else
 {
	 $$$TRACE(  "REFRESH NOW "  _ (nextdateref - todayInt) _ " : " _ (nexttimeref - nowInt))
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddRepCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddNcidCache)
	  // Get refresh date and time
	  set hddUpdateDay = ..HddUpdateDay ; Sunday: 0, Monday: 1, Saturday: 6
	  if ( (hddUpdateDay < 0) || (hddUpdateDay > 7))
	  {
		  $$$LOGERROR("HddUpdateDay not set, value should be between 0 and 7")
		  return
	  }

      // Calculate next refresh date
	  set dayOfWeek = $ZDATE($HOROLOG,10)
	  set daysLeft = $SELECT( (dayOfWeek > hddUpdateDay) : (7 - dayOfWeek + hddUpdateDay),(dayOfWeek = hddUpdateDay) : 7, 1 : (hddUpdateDay - dayOfWeek) )
	  set refdatezh = todayInt + daysLeft

	  // Next refresh time
      SET hddUpdateTime= ..HddUpdateTime  ; format: "hh:mm" (24-hour clock).
      if ( ($MATCH(hddUpdateTime, "\d\d:\d\d") = 1) || ($MATCH(hddUpdateTime, "\d:\d\d") = 1) )
 	  {

 	  	set hddUpdateTimezh = $ZTIMEH(hddUpdateTime,2)
 	  	if (hddUpdateTimezh <= 0)
 	  	{
	 	  	$$$LOGERROR("HddUpdateTime not set")
	 		  return
 	  	}
 	  }
 	  else
 	  {
 	  	$$$LOGERROR("HddUpdateTime not set correctly: HH:MM")
	 	  return
 	  }

      set ^NextRef(1)= refdatezh _ "," _ hddUpdateTimezh
      $$$TRACE(  "NEXT REFRESH: " _ $ZDATETIME(^NextRef(1)))
 }
